// Sidebar.tsx

import React, { useEffect, useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";

const PRIMARY = "#EA580C";
const PRIMARY_LIGHT = "#FFF4EE";
const PRIMARY_TEXT = "#EA580C";

export type NavItem = {
  id: string;
  label: string;
  path: string;
  icon?: string;
};

export type NavGroup = {
  id: string;
  label: string;
  path: string;
  icon?: string;
  children?: NavItem[];
};

interface SidebarProps {
  features: NavGroup[];
  collapsed?: boolean;
  onToggle?: () => void;
  onNavigate?: (item: NavItem) => void;
}

const WeeraIcon: React.FC<{ size?: number }> = ({ size = 22 }) => (
  <img
    src="/images/app_icon_fg.png"
    width={size}
    height={size}
    alt="Weera logo"
    style={{ objectFit: "contain", display: "block" }}
  />
);

export const Sidebar: React.FC<SidebarProps> = ({
  features,
  collapsed = false,
  onToggle,
  onNavigate,
}) => {
  const navigate = useNavigate();
  const location = useLocation();

  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
    };

    window.addEventListener("resize", handleResize);

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    users: true,
  });

  const width = collapsed
    ? isMobile
      ? 70
      : 80
    : isMobile
    ? 240
    : 280;

  const handleClick = (item: NavItem) => {
    navigate(item.path);
    onNavigate?.(item);
  };

  const toggleGroup = (groupId: string) => {
    setOpenGroups((prev) => ({
      ...prev,
      [groupId]: !prev[groupId],
    }));
  };

  const isPathActive = (path: string) => {
    return location.pathname === path;
  };

  return (
    <aside
      style={{
        width,
        minWidth: width,
        height: "100vh",
        background: "#F9FBFC",
        borderRight: "1px solid #E1E4EA",
        boxSizing: "border-box",
        padding: collapsed ? "12px 8px" : "12px",
        display: "flex",
        flexDirection: "column",
        gap: 24,
        transition: "all 0.25s ease",
        overflow: "hidden",
        position: "fixed",
        top: 0,
        left: 0,
        zIndex: 100,
      }}
    >
      {/* HEADER */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: collapsed ? "center" : "space-between",
          gap: 8,
        }}
      >
        {!collapsed ? (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
            }}
          >
            <div
              style={{
                width: 38,
                height: 38,
                borderRadius: 10,
                background: PRIMARY,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <WeeraIcon size={28} />
            </div>

            <span
              style={{
                fontWeight: 700,
                fontSize: 16,
                color: "#0F172A",
              }}
            >
              WEERA
            </span>
          </div>
        ) : (
          <div
            style={{
              width: 42,
              height: 42,
              borderRadius: 10,
              background: PRIMARY,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              margin: "0 auto",
            }}
          >
            <WeeraIcon size={28} />
          </div>
        )}

        {!isMobile && (
          <button
            onClick={onToggle}
            style={{
              border: "1px solid #E2E8F0",
              background: "#fff",
              borderRadius: 8,
              width: 34,
              height: 34,
              cursor: "pointer",
              flexShrink: 0,
            }}
          >
            ☰
          </button>
        )}
      </div>

      {/* NAVIGATION */}
      <nav
        style={{
          flex: 1,
          overflowY: "auto",
          overflowX: "hidden",
        }}
      >
        <ul
          style={{
            listStyle: "none",
            padding: 0,
            margin: 0,
            display: "flex",
            flexDirection: "column",
            gap: 6,
          }}
        >
          {features.map((group) => {
            const groupActive = isPathActive(group.path);
            const hasChildren = !!group.children?.length;
            const isOpen = openGroups[group.id];

            return (
              <React.Fragment key={group.id}>
                {/* PARENT */}
                <li>
                  <button
                    onClick={() => {
                      if (hasChildren && !collapsed) {
                        toggleGroup(group.id);
                      } else {
                        handleClick({
                          id: group.id,
                          label: group.label,
                          path: group.path,
                          icon: group.icon,
                        });
                      }
                    }}
                    title={collapsed ? group.label : undefined}
                    style={{
                      width: "100%",
                      border: "none",
                      background: groupActive
                        ? PRIMARY_LIGHT
                        : "transparent",
                      borderRadius: 12,
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: collapsed
                        ? "center"
                        : "flex-start",
                      gap: 12,
                      padding: collapsed
                        ? "14px 0"
                        : "14px 16px",
                      color: groupActive
                        ? PRIMARY_TEXT
                        : "#475569",
                      fontWeight: groupActive ? 600 : 500,
                      transition: "all 0.2s ease",
                      borderLeft: groupActive
                        ? `3px solid ${PRIMARY}`
                        : "3px solid transparent",
                    }}
                  >
                    <span
                      style={{
                        fontSize: 18,
                        flexShrink: 0,
                      }}
                    >
                      {group.icon}
                    </span>

                    {!collapsed && (
                      <span
                        style={{
                          overflow: "hidden",
                          textOverflow: "ellipsis",
                        }}
                      >
                        {group.label}
                      </span>
                    )}
                  </button>
                </li>

                {/* CHILDREN */}
                {!collapsed &&
                  hasChildren &&
                  isOpen &&
                  group.children?.map((child) => {
                    const childActive = isPathActive(child.path);

                    return (
                      <li
                        key={child.id}
                        style={{
                          paddingLeft: 18,
                        }}
                      >
                        <button
                          onClick={() => handleClick(child)}
                          style={{
                            width: "100%",
                            border: "none",
                            background: childActive
                              ? PRIMARY_LIGHT
                              : "transparent",
                            borderRadius: 10,
                            cursor: "pointer",
                            display: "flex",
                            alignItems: "center",
                            gap: 10,
                            padding: "10px 14px",
                            color: childActive
                              ? PRIMARY_TEXT
                              : "#64748B",
                            fontWeight: childActive ? 600 : 400,
                            transition: "all 0.2s ease",
                            borderLeft: childActive
                              ? `3px solid ${PRIMARY}`
                              : "3px solid transparent",
                          }}
                        >
                          <span>{child.label}</span>
                        </button>
                      </li>
                    );
                  })}
              </React.Fragment>
            );
          })}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
